\mathsf{Ctx}_{\mathsf{Rec}}
=
\bigcup_{n\in\mathbb N}
\left\{
\langle x_i:A_i\rangle_{i<n}:
\forall i<n\ (x_i\in\mathsf{Var}_{\mathsf{Rec}}\land A_i\in\mathsf{Ty}_{\mathsf{Rec}})
\land
\forall i<j<n\ x_i\ne x_j
\right\}.

(\lambda y:A.t)[x:=s]=
\begin{cases}
\lambda y:A.t,&y=x,\\
\lambda y:A.t[x:=s],&y\ne x,\ y\notin\operatorname{FV}(s),\\
\lambda z:A.(t[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}(s),
\end{cases}
